import{_ as t,c as a,o as i,ae as n}from"./chunks/framework.Bi6zybwU.js";const m=JSON.parse('{"title":"Basic Settings","description":"Basic Settings","frontmatter":{"title":"Basic Settings","description":"Basic Settings"},"headers":[],"relativePath":"guide/column-settings/basic-settings.md","filePath":"guide/column-settings/basic-settings.md"}'),o={name:"guide/column-settings/basic-settings.md"};function s(l,e,r,c,u,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="basic-settings" tabindex="-1">Basic Settings <a class="header-anchor" href="#basic-settings" aria-label="Permalink to &quot;Basic Settings&quot;">​</a></h1><p>Ninja Tables has several custom settings options to create a table. Basic Settings is where you can establish a column with basic choices like column name, column key, data type, and responsive breakpoints. Let&#39;s have a look at this simple guide to learn how to create a column with these <strong>Basic Settings</strong>.</p><h2 id="column-basic-settings-in-ninja-tables" tabindex="-1">Column Basic Settings in Ninja Tables <a class="header-anchor" href="#column-basic-settings-in-ninja-tables" aria-label="Permalink to &quot;Column Basic Settings in Ninja Tables&quot;">​</a></h2><ul><li>Go to a table created by <strong>Ninja Tables</strong> first and then hover over any column to find the settings icon. Or,</li><li>You can move to the <strong>Table Configuration</strong> tab and click the edit icon. Select Basic Settings. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-UI-table-column-1024x461.webp" alt="New UI table column"></li><li>Here you will notice various basic options like Column Name, Column Key, Data Type, and Responsive Breakpoints.</li></ul><h3 id="column-name" tabindex="-1">Column Name <a class="header-anchor" href="#column-name" aria-label="Permalink to &quot;Column Name&quot;">​</a></h3><p>To set the <strong>header title</strong> for the specific column, use this option to provide the name. This field must be filled out. One more important thing is that the Column Name is <strong>HTML-supported</strong>.</p><h3 id="column-key" tabindex="-1">Column Key <a class="header-anchor" href="#column-key" aria-label="Permalink to &quot;Column Key&quot;">​</a></h3><p>The column key is for data mapping, exporting, and importing table data. The column key will generate <strong>automatically</strong> when you enter the column name for your table.</p><h3 id="data-type" tabindex="-1">Data Type <a class="header-anchor" href="#data-type" aria-label="Permalink to &quot;Data Type&quot;">​</a></h3><p>Various Data Types are available to construct columns according to your needs. For example, text area, buttons, lightbox, HTML, etc. To learn more, go to this <a href="https://ninjatables.com/docs-category/column-data-types/" target="_blank" rel="noreferrer">documentation</a>, and you will know better.</p><h3 id="responsive-breakpoints" tabindex="-1"><strong>Responsive Breakpoint</strong>s <a class="header-anchor" href="#responsive-breakpoints" aria-label="Permalink to &quot;**Responsive Breakpoint**s&quot;">​</a></h3><p>Ninja Tables gives you the option to choose among 6 distinct breakpoints. <img src="https://ninjatables.com/wp-content/uploads/2025/05/New-Ui-responsive-breakpoints-1024x675.webp" alt="New Ui responsive breakpoints"></p><ul><li>Always show in all devices</li><li>Hidden on desktop</li><li>Initial hidden mobile</li><li>Initial hidden mobile and tab</li><li>Initial hidden mobile, tab, and regular computers</li><li>Totally hidden on all devices You can decide what column you don&#39;t want to appear on what device. When activated, the table will show a &quot;+&quot; sign and the hidden column will appear if you click it. Here&#39;s an example table [ninja_tables id=&quot;4697&quot;] This is how easily you can configure the Basic Settings of a table in Ninja Tables.</li></ul>',13)])])}const p=t(o,[["render",s]]);export{m as __pageData,p as default};
